-- Light Dash - initial Postgres schema.
--
-- The Postgres twin of server/schema.sql (which is SQLite). Keep the two in
-- step: test/schema-parity.mjs fails if their tables or columns drift apart.
--
-- On Netlify Database this file is applied by Netlify during deploy. On any
-- other Postgres, apply it with `node server/migrate.mjs`. Never edit it once
-- applied - add a new, later-dated migration instead.
--
-- Differences from the SQLite schema, and why:
--   * ids are identity columns, generated BY DEFAULT so existing rows can be
--     copied in with their ids unchanged;
--   * money and other decimals are DOUBLE PRECISION: Postgres's REAL is only a
--     4-byte float and cannot hold a figure like 86800000 exactly;
--   * case-insensitive emails use a unique index on lower(email);
--   * tables are created in dependency order, since Postgres checks a foreign
--     key's target exists when the table is created.

CREATE TABLE departments (
  id         INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  name       TEXT NOT NULL UNIQUE,
  created_at TEXT NOT NULL
);

CREATE TABLE employees (
  id              INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  first_name      TEXT NOT NULL,
  last_name       TEXT NOT NULL,
  email           TEXT,
  phone           TEXT,
  department_id   INTEGER REFERENCES departments(id),
  job_title       TEXT,
  employment_type TEXT NOT NULL DEFAULT 'Full-time',
  start_date      TEXT,
  status          TEXT NOT NULL DEFAULT 'Active',
  created_at      TEXT NOT NULL
);
CREATE UNIQUE INDEX ux_employees_email ON employees (lower(email));

CREATE TABLE users (
  id            INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  email         TEXT    NOT NULL,
  name          TEXT    NOT NULL,
  role          TEXT    NOT NULL DEFAULT 'viewer',
  scopes        TEXT    NOT NULL DEFAULT '[]',
  password_hash TEXT,
  password_salt TEXT,
  employee_id   INTEGER REFERENCES employees(id),
  active        INTEGER NOT NULL DEFAULT 1,
  created_at    TEXT    NOT NULL,
  last_seen_at  TEXT,
  note          TEXT
);
CREATE UNIQUE INDEX ux_users_email ON users (lower(email));

CREATE TABLE sessions (
  id           INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  user_id      INTEGER NOT NULL REFERENCES users(id) ON DELETE CASCADE,
  token_hash   TEXT    NOT NULL UNIQUE,
  kind         TEXT    NOT NULL DEFAULT 'session',
  label        TEXT,
  created_at   TEXT    NOT NULL,
  expires_at   TEXT,
  last_used_at TEXT,
  user_agent   TEXT
);

CREATE TABLE login_attempts (
  key      TEXT PRIMARY KEY,
  first_at TEXT    NOT NULL,
  count    INTEGER NOT NULL
);

CREATE TABLE audit_log (
  id            INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  at            TEXT    NOT NULL,
  actor_user_id INTEGER REFERENCES users(id),
  actor_label   TEXT    NOT NULL,
  entity        TEXT    NOT NULL,
  entity_id     INTEGER NOT NULL,
  action        TEXT    NOT NULL,
  changes       TEXT    NOT NULL
);

CREATE TABLE time_off (
  id          INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  employee_id INTEGER NOT NULL REFERENCES employees(id),
  kind        TEXT NOT NULL DEFAULT 'Vacation',
  start_date  TEXT NOT NULL,
  end_date    TEXT NOT NULL,
  status      TEXT NOT NULL DEFAULT 'Requested',
  note        TEXT,
  created_at  TEXT NOT NULL
);

CREATE TABLE goals (
  id          INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  employee_id INTEGER NOT NULL REFERENCES employees(id),
  title       TEXT NOT NULL,
  period      TEXT,
  progress    INTEGER NOT NULL DEFAULT 0,
  status      TEXT NOT NULL DEFAULT 'Not started',
  review_note TEXT,
  created_at  TEXT NOT NULL
);

CREATE TABLE companies (
  id         INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  name       TEXT NOT NULL UNIQUE,
  industry   TEXT,
  website    TEXT,
  phone      TEXT,
  address    TEXT,
  created_at TEXT NOT NULL
);

CREATE TABLE contacts (
  id         INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  first_name TEXT NOT NULL,
  last_name  TEXT NOT NULL,
  email      TEXT,
  phone      TEXT,
  job_title  TEXT,
  company_id INTEGER REFERENCES companies(id),
  created_at TEXT NOT NULL
);

CREATE TABLE deals (
  id             INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  title          TEXT NOT NULL,
  company_id     INTEGER REFERENCES companies(id),
  contact_id     INTEGER REFERENCES contacts(id),
  owner_id       INTEGER REFERENCES employees(id),
  value          DOUBLE PRECISION NOT NULL DEFAULT 0,
  stage          TEXT NOT NULL DEFAULT 'Lead',
  expected_close TEXT,
  created_at     TEXT NOT NULL
);

CREATE TABLE projects (
  id         INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  name       TEXT NOT NULL UNIQUE,
  company_id INTEGER REFERENCES companies(id),
  manager_id INTEGER REFERENCES employees(id),
  status     TEXT NOT NULL DEFAULT 'Planned',
  start_date TEXT,
  end_date   TEXT,
  budget     DOUBLE PRECISION,
  created_at TEXT NOT NULL
);

CREATE TABLE tasks (
  id          INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  project_id  INTEGER NOT NULL REFERENCES projects(id),
  title       TEXT NOT NULL,
  assignee_id INTEGER REFERENCES employees(id),
  status      TEXT NOT NULL DEFAULT 'To do',
  priority    TEXT NOT NULL DEFAULT 'Medium',
  due_date    TEXT,
  created_at  TEXT NOT NULL
);

CREATE TABLE timesheets (
  id          INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  employee_id INTEGER NOT NULL REFERENCES employees(id),
  project_id  INTEGER REFERENCES projects(id),
  work_date   TEXT NOT NULL,
  hours       DOUBLE PRECISION NOT NULL CHECK (hours > 0 AND hours <= 24),
  note        TEXT,
  created_at  TEXT NOT NULL
);

CREATE TABLE invoices (
  id         INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  number     TEXT NOT NULL UNIQUE,
  company_id INTEGER NOT NULL REFERENCES companies(id),
  project_id INTEGER REFERENCES projects(id),
  issue_date TEXT NOT NULL,
  due_date   TEXT,
  status     TEXT NOT NULL DEFAULT 'Draft',
  tax_rate   DOUBLE PRECISION NOT NULL DEFAULT 0,
  subtotal   DOUBLE PRECISION NOT NULL DEFAULT 0,
  tax        DOUBLE PRECISION NOT NULL DEFAULT 0,
  total      DOUBLE PRECISION NOT NULL DEFAULT 0,
  notes      TEXT,
  created_at TEXT NOT NULL
);

CREATE TABLE invoice_items (
  id          INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  invoice_id  INTEGER NOT NULL REFERENCES invoices(id) ON DELETE CASCADE,
  position    INTEGER NOT NULL,
  description TEXT    NOT NULL,
  quantity    DOUBLE PRECISION NOT NULL,
  unit_price  DOUBLE PRECISION NOT NULL,
  amount      DOUBLE PRECISION NOT NULL
);

CREATE TABLE expenses (
  id          INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  spent_on    TEXT NOT NULL,
  category    TEXT NOT NULL,
  vendor      TEXT,
  amount      DOUBLE PRECISION NOT NULL CHECK (amount >= 0),
  project_id  INTEGER REFERENCES projects(id),
  employee_id INTEGER REFERENCES employees(id),
  status      TEXT NOT NULL DEFAULT 'Submitted',
  note        TEXT,
  created_at  TEXT NOT NULL
);

CREATE TABLE executives (
  id         INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  name       TEXT NOT NULL UNIQUE,
  role       TEXT,
  email      TEXT,
  created_at TEXT NOT NULL
);

CREATE TABLE kpis (
  id               INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  executive_id     INTEGER NOT NULL REFERENCES executives(id),
  objective        TEXT    NOT NULL,
  deliverable      TEXT    NOT NULL,
  month            TEXT,
  target_date      TEXT,
  priority         TEXT    NOT NULL DEFAULT 'High',
  status           TEXT    NOT NULL DEFAULT 'Not Started',
  percent_complete INTEGER NOT NULL DEFAULT 0,
  mechanism        TEXT,
  target_value     DOUBLE PRECISION,
  realized         DOUBLE PRECISION,
  income_stage     TEXT,
  review_note      TEXT,
  source_row       INTEGER,
  created_at       TEXT    NOT NULL,
  UNIQUE (executive_id, objective, deliverable)
);

CREATE INDEX idx_kpis_exec      ON kpis(executive_id);
CREATE INDEX idx_audit_entity   ON audit_log(entity, entity_id, at);
CREATE INDEX idx_audit_at       ON audit_log(at);
CREATE INDEX idx_sessions_user  ON sessions(user_id);
CREATE INDEX idx_employees_dept ON employees(department_id);
CREATE INDEX idx_deals_stage    ON deals(stage);
CREATE INDEX idx_tasks_project  ON tasks(project_id, status);
CREATE INDEX idx_time_date      ON timesheets(work_date);
CREATE INDEX idx_invoice_status ON invoices(status, issue_date);
CREATE INDEX idx_items_invoice  ON invoice_items(invoice_id);
CREATE INDEX idx_expenses_date  ON expenses(spent_on);
